<script setup>
import {computed,onMounted,ref} from 'vue'
import {operationsStats,activeAlerts} from '../domain/operations.js'
import ChartPanel from './ChartPanel.vue'
const props=defineProps({source:Object,client:Object,accountKey:{type:String,default:'demo'},showStatistics:{type:Boolean,default:true}}),emit=defineEmits(['device','order'])
const scene=ref(''),from=ref(''),to=ref(''),pendingOnly=ref(true),acks=ref([]),selected=ref(null),note=ref(''),busy=ref(false),error=ref('')
const storageKey='ebike-alert-ack:'+props.accountKey
const stats=computed(()=>operationsStats(props.source,{from:from.value,to:to.value,scene:scene.value})),ackMap=computed(()=>new Map(acks.value.map(a=>[a.alertKey,a])))
const alerts=computed(()=>activeAlerts(props.source).filter(a=>(!scene.value||props.source.stations.find(s=>s.id===a.stationId)?.scene===scene.value)&&(!pendingOnly.value||!ackMap.value.has(a.key))))
const trend=computed(()=>({color:['#7568d5'],tooltip:{trigger:'axis'},grid:{left:52,right:24,bottom:35,top:25},xAxis:{type:'category',data:stats.value.days.map(d=>d.date.slice(5))},yAxis:{type:'value',name:'元',min:0},series:[{name:'已结算金额',type:'line',smooth:true,data:stats.value.days.map(d=>Number(d.amount.toFixed(2)))}]}))
const peaks=computed(()=>({color:['#39a6ae'],tooltip:{trigger:'axis'},grid:{left:45,right:20,bottom:35,top:25},xAxis:{type:'category',data:stats.value.hours.map((_,i)=>i+'时'),axisLabel:{interval:3}},yAxis:{type:'value',name:'订单数',min:0,minInterval:1},series:[{name:'启动订单',type:'bar',data:stats.value.hours}]}))
async function reload(){error.value='';try{if(props.client)acks.value=await props.client.alertAcks();else{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');acks.value=Array.isArray(saved)?saved:[]}}catch(e){error.value='告警确认记录读取失败：'+e.message}}
async function acknowledge(){if(!selected.value||busy.value)return;if(note.value.trim().length<2){error.value='请填写2—500字的核对说明';return}busy.value=true;error.value='';try{const key=selected.value.key;if(props.client)await props.client.ackAlert({alertKey:key,note:note.value.trim()});else{const record={alertKey:key,note:note.value.trim(),username:props.accountKey,updatedAt:new Date().toISOString()};const next=[record,...acks.value.filter(a=>a.alertKey!==key)];localStorage.setItem(storageKey,JSON.stringify(next));acks.value=next}selected.value=null;if(props.client)await reload()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(reload)
</script>
<template><section class="management-page operations"><header class="management-heading"><div><h1>{{showStatistics?'运营分析与设备告警':'设备告警'}}</h1><p>金额统计采用已结束订单账单；告警确认只记录核对情况，不解除设备故障或充电占用。</p></div></header><div class="filter-bar"><select v-model="scene" aria-label="运营场景"><option value="">全部场景</option><option>校园</option><option>住宅小区</option><option>园区</option><option>未分类</option></select><template v-if="showStatistics"><label>订单开始日期 <input v-model="from" type="date" aria-label="统计开始日期"/></label><label>至 <input v-model="to" type="date" aria-label="统计结束日期"/></label></template><button class="outline-button" @click="scene='';from='';to=''">重置筛选</button></div><p v-if="from&&to&&from>to" class="remote-error">开始日期晚于结束日期，请调整。</p><p v-if="error" class="remote-error" role="alert">{{error}}</p>
<template v-if="showStatistics"><div class="remote-metrics"><article><span>已结算金额 / 元</span><strong>{{stats.amount.toFixed(2)}}</strong></article><article><span>已结算电量 / kWh</span><strong>{{stats.energy.toFixed(3)}}</strong></article><article><span>完成订单 / 全部订单</span><strong>{{stats.completed}} / {{stats.orders}}</strong></article><article><span>失败或异常订单占比</span><strong>{{stats.orders?(stats.failed/stats.orders*100).toFixed(1):'0.0'}}%</strong></article></div><p v-if="stats.missingBills" class="remote-error">{{stats.missingBills}}条历史账单金额缺失，未计入金额合计。</p><div class="operation-charts"><article><h2>已结算金额趋势</h2><ChartPanel :option="trend" label="按订单开始日期汇总的已结算金额趋势"/></article><article><h2>充电启动时段</h2><ChartPanel :option="peaks" label="订单启动小时分布"/></article></div><div class="management-table-wrap"><table class="management-table"><thead><tr><th>站点</th><th>场景</th><th>当前插座占用率</th><th>完成订单</th><th>结算电量 / kWh</th><th>结算金额 / 元</th></tr></thead><tbody><tr v-for="s in stats.stations" :key="s.id"><td>{{s.name}}</td><td>{{s.scene}}</td><td>{{s.occupied}} / {{s.sockets}}（{{s.sockets?(s.occupied/s.sockets*100).toFixed(1):'0.0'}}%）</td><td>{{s.completed}}</td><td>{{s.energy.toFixed(3)}}</td><td>{{s.amount.toFixed(2)}}</td></tr><tr v-if="!stats.stations.length"><td colspan="6">暂无符合条件的站点</td></tr></tbody></table></div><p class="form-hint">插座占用率为当前活动任务插座数 / 全部插座数，与历史日期筛选无关。金额趋势按订单开始日期归属，不等同实收现金流。</p></template>
<div class="section-row alert-heading"><h2>设备告警（{{alerts.length}}）</h2><label><input v-model="pendingOnly" type="checkbox"/>只看未确认</label><button class="outline-button" @click="reload">刷新确认记录</button></div><div class="management-table-wrap"><table class="management-table"><thead><tr><th>级别 / 类型</th><th>站点</th><th>说明</th><th>确认记录</th><th>操作</th></tr></thead><tbody><tr v-for="a in alerts" :key="a.key"><td>{{a.level}} · {{a.title}}</td><td>{{source.stations.find(s=>s.id===a.stationId)?.name||'—'}}</td><td>{{a.body}}</td><td>{{ackMap.get(a.key)?.note||'待核对'}}<br/><small>{{ackMap.get(a.key)?.username}}</small></td><td><button v-if="a.deviceId" class="table-link" @click="emit('device',a.deviceId)">查看设备</button><button v-if="a.orderId" class="table-link" @click="emit('order',a.orderId)">查看订单</button><button class="table-link" @click="selected=a;note=ackMap.get(a.key)?.note||''">记录核对</button></td></tr><tr v-if="!alerts.length"><td colspan="5">暂无符合条件的告警</td></tr></tbody></table></div>
<div v-if="selected" class="modal-shade"><section class="modal-card" role="dialog" aria-modal="true" aria-label="记录告警核对"><header><h2>{{selected.title}}</h2></header><div class="remote-detail"><p>{{selected.body}}</p><textarea v-model="note" class="ack-note" maxlength="500" placeholder="记录核对情况与后续处理安排" aria-label="告警核对说明"/><p v-if="error" role="alert">{{error}}</p></div><footer><button class="outline-button" :disabled="busy" @click="selected=null">取消</button><button class="soft-button active" :disabled="busy" @click="acknowledge">{{busy?'正在保存…':'确认并记录'}}</button></footer></section></div>
</section></template>
<style scoped>.remote-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:1.5rem}.remote-metrics article{background:white;border:1px solid #e5e0ee;border-radius:10px;padding:20px;display:flex;flex-direction:column;gap:14px}.remote-metrics strong{font-size:1.65rem;color:#655685}.remote-metrics span{font-size:.85rem}.remote-error{padding:12px;color:#a9415a}.remote-metrics article{min-width:0}@media(max-width:800px){.remote-metrics{grid-template-columns:1fr 1fr}}.operations h2{font-size:1.1rem;font-weight:500}.operation-charts{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;padding:1.5rem}.operation-charts article{min-width:0;background:#fff;border:1px solid #e8e5ef;border-radius:10px;padding:1rem}.operation-charts .chart-canvas{height:250px}.operations .form-hint{padding:1rem}.alert-heading{display:flex;align-items:center;gap:1rem;padding:1.5rem}.alert-heading h2{margin-right:auto}.ack-note{width:100%;min-height:120px;padding:12px;box-sizing:border-box;border:1px solid #ddd6e8;border-radius:8px;font:inherit}.filter-bar label{display:flex;align-items:center;gap:.5rem;font-size:.9rem}@media(max-width:900px){.operation-charts{grid-template-columns:1fr}.alert-heading{flex-wrap:wrap}}</style>
